"""GENERATED by make_walker.py - DO NOT EDIT. Frozen copy of
agents/market_intelligence/live_fill_counterfactuals.py::walk_arm (git blob e9098c36) + the hook set.
See walker_diff.out for every line that differs from the live walker."""
from __future__ import annotations

from datetime import date
from types import SimpleNamespace
from typing import Any, Optional

from agents.market_intelligence.broker.exit_logic import (
    apply_daily_exit_step, depth_stop_price, seed_exit_state)
from agents.market_intelligence.live_fill_counterfactuals import (
    HARVEST_RULES, HORIZON_SESSIONS, TRAIL_RULES)


def _fresh_walk() -> dict[str, Any]:
    return {"status": None, "reason": None, "exits": [], "final_reason": None,
            "partial_fired": False, "gap_through": False, "exit_session": None,
            "sessions_walked": 0, "pnl_per_share": None, "mark_pnl_per_share": None,
            "pending_at": None, "remaining": 1.0}


def walk_cand(*, entry: float, stop: float, target: Optional[float],
             day0_bars: Optional[list[dict]], fill_idx: int,
             sessions: list[tuple[date, Optional[dict]]], prior_closes: list[float],
             harvest: str, fill_day: date,
             breakeven_at_partial: bool = True, trail_prior_closes: bool = True,
             ladder_partial: bool = False, horizon: int = HORIZON_SESSIONS,
             breakeven_at_r: Optional[float] = None,
             r_frame_ps: Optional[float] = None,
             trail_mode: str = "sma",
             pivot_stops: Optional[list] = None,
             character: Optional[dict] = None,
             depth_exit: bool = False,
             depth_adr20_pct: Optional[float] = None,
             hook: Optional[dict] = None) -> dict:  # HOOK: the only new parameter
    """Walk ONE arm from the fill bar to settlement, on one fractional share.

    `depth_exit` (#687, 2026-10-11): walk the DEPTH exit a row stamped `exit_rule='depth'` runs
    (module docstring, "#687"). Day 0 is unchanged (the 16:45 job skips the alert day). From
    session 1: the resting stop becomes `exit_logic.depth_stop_price(line=today's effective
    stop, hard_stop=this arm's stop, entry, breakeven_active, depth_adr20_pct)` under the same
    raise-only ratchet (the broker's `update_stop`), so it sits one ADR20 under the line instead
    of on it; a close below the line (the ladder's `sma_trail_stop`, unchanged) books the sale at
    the NEXT session's OPEN — `pending` until that bar is stored. `depth_adr20_pct` is the
    FRACTION from `adr20_pct_from_bars` (None = no ADR20 → the stop rests at the hard/breakeven
    floor, as live does). Only the live ladder on the SMA line hosts it (ValueError otherwise —
    a silent fall-back would record today's exit under a depth stamp). DEFAULT False =
    byte-identical to before.

    `trail_mode` (#631): 'sma' (DEFAULT, byte-identical to before #631 — the live
    max(SMA10, SMA20)); 'pivot_swing' reads `pivot_stops[i]` for session i (from
    pivot_stops_for_sessions) as the trail line; 'character_ma' trails the profile's home
    MA × (1 − undercut_p80) — `character` is REQUIRED for it (ValueError otherwise: a
    silent fall-back to the SMA trail would record the wrong arm under the right name).
    The trail only ever enters the ladder's max() — day 0 (minute walk) is unchanged.

    `day0_bars`: the fill day's 1-min bars {m,o,h,l,c}, `fill_idx` = the fill minute's
    index (None = minutes unavailable → pending). `sessions`: [(date, bar|None)] for the
    trading sessions AFTER the fill day, oldest first, already capped at `horizon`; a None
    bar is a gap and BLOCKS the walk (pending at that date). Mirrors
    scripts/ep_replay._walk_leg for the live rule and the #2 lineage's t3 (module docstring
    lists the three deliberate deviations).

    `breakeven_at_r` (#545, 2026-09-06): the PRICE-ARMED breakeven, independent of the
    partial — the stop raises to entry the first time price trades at
    entry + breakeven_at_r × r_frame_ps, whether or not a partial has fired. Only
    meaningful on harvest="live_ladder" (raises ValueError otherwise — a silent no-op on
    a harvest with no breakeven floor is worse than a loud reject). `r_frame_ps` is the
    SAME R frame the target uses (entry − orb_low for MAGNA53's ORB frame); defaults to
    entry − stop when not given, mirroring ep_replay._walk_leg's `r_frame_ps` exactly.
    AMBIGUITY: a bar that reaches the trigger AND also trades at/below entry while not yet
    armed has two unorderable paths at this grain (armed-then-stopped vs survived-then-
    armed) → abstain, never guessed — the same discipline ep_replay's `be_ambiguous` uses,
    reproduced verbatim here (not imported: ep_replay cannot be imported into the market
    agent, module docstring's WHAT IT MIRRORS).

    status: settled | abstain | horizon | pending. R is left to the caller (pnl_per_share /
    (entry − stop)); `mark_pnl_per_share` is set only at the horizon."""
    if harvest not in HARVEST_RULES:
        raise ValueError(f"unknown harvest rule {harvest!r}")
    if trail_mode not in TRAIL_RULES:
        raise ValueError(f"unknown trail rule {trail_mode!r}")
    if trail_mode == "character_ma" and not character:
        raise ValueError("trail_mode 'character_ma' needs a character profile; "
                         "record the arm unscoreable instead of walking it")
    if trail_mode == "pivot_swing" and pivot_stops is None:
        raise ValueError("trail_mode 'pivot_swing' needs pivot_stops (pivot_stops_for_sessions)")
    if depth_exit and (harvest != "live_ladder" or trail_mode != "sma"):
        raise ValueError(f"depth_exit needs the live ladder on the SMA line, got harvest "
                         f"{harvest!r} / trail_mode {trail_mode!r}")
    out = _fresh_walk()
    # ── HOOK SETUP (everything between the HOOK markers is new; nothing else in this function moved) ──
    _H = hook or {}
    _rule, _frame, _ref = _H.get("rule"), _H.get("frame"), _H.get("ref")
    _trace = _H.get("trace")
    _atr14 = _H.get("atr14")
    trig_rec: dict = {}              # which -> {"idx": session index (0 = day 0), "F": stop resting then}
    out["trig"] = trig_rec           # control instrumentation: BOTH frames' triggers are recorded, acted on or not

    def note_trigger(which, idx, F):
        if which not in trig_rec:
            trig_rec[which] = {"idx": idx, "F": F}

    def _owned(idx):
        # the candidate owns the close decision from its trigger bar (inclusive); a day-0 trigger
        # hands over at session 1 (the 16:45 job never decides on the entry day)
        if _rule is None:
            return False
        if _H.get("mutate_early") and _frame not in trig_rec:
            note_trigger(_frame, idx, max(resting, entry))      # TEST ONLY: own the walk before any trigger
        rec = trig_rec.get(_frame)
        return rec is not None and (rec["idx"] == 0 or idx >= rec["idx"])

    def _synth_step(idx, d, b):
        # The candidate's decision for rules with NO moving average line (hold-N, chandelier,
        # give-back). Mirrors apply_daily_exit_step: (1) the resting stop is tested on the bar's
        # low first, at the stop price (the caller then fills at the open on a gap); (2) then the rule.
        rec = trig_rec[_frame]
        rem = state["remaining_shares"]
        ex = list(state.get("exits") or [])
        base = dict(new_remaining=rem, new_partial_taken=state["partial_taken"],
                    new_breakeven_active=state["breakeven_active"],
                    new_running_closes=list(state.get("running_closes") or []) + [b["c"]], new_exits=ex)
        if resting and b["l"] <= resting:
            leg = {"time": str(d), "price": resting, "reason": "stop_hit", "shares": rem,
                   "pnl": (resting - entry) * rem}
            return SimpleNamespace(**{**base, "closed": True, "close_reason": "stop_hit",
                                      "close_price": resting, "effective_stop": resting,
                                      "new_remaining": 0, "new_exits": ex + [leg]})
        level, why, px = resting, None, None
        if _rule.startswith("t") and _rule.endswith("_be"):
            if idx - rec["idx"] >= int(_rule[1:-3]):
                why, px = "time_close", b["c"]                       # market-on-close, date known in advance
        elif _rule in ("gb25_be", "gb50_be"):
            keep = 0.75 if _rule == "gb25_be" else 0.50
            if held_peak > entry and b["c"] < entry + keep * (held_peak - entry):
                why, px = "sma_trail_stop", b["c"]                   # decided on the close, sold at the next open
        elif _rule in ("atr1_be", "atr2_be"):
            k = 1.0 if _rule == "atr1_be" else 2.0
            if _atr14:
                level = max(resting, held_peak - k * _atr14)         # rests from the NEXT session
        else:
            raise ValueError(f"_synth_step: unknown rule {_rule!r}")
        if why:
            leg = {"time": str(d), "price": px, "reason": why, "shares": rem, "pnl": (px - entry) * rem}
            return SimpleNamespace(**{**base, "closed": True, "close_reason": why, "close_price": px,
                                      "effective_stop": level, "new_remaining": 0, "new_exits": ex + [leg]})
        return SimpleNamespace(**{**base, "closed": False, "close_reason": None, "close_price": None,
                                  "effective_stop": level})

    def _note_depth(idx, d, step, dsp, resting_before):
        if _trace is None:
            return
        floor = max(stop, entry) if (state["breakeven_active"] and entry) else stop
        _trace.setdefault("depth", []).append(dict(
            idx=idx, d=str(d), line=step.effective_stop, adr20=depth_adr20_pct, floor=round(floor, 2),
            depth_stop=dsp, resting_before=resting_before,
            binding=bool(dsp > round(floor, 2) + 1e-9), raised=bool(dsp > resting_before + 1e-9)))
    # ── END HOOK SETUP ──
    if stop is None or entry is None or entry - stop <= 0:
        out.update(status="abstain", reason="nonpositive_risk_per_share")
        return out
    if day0_bars is None or fill_idx is None or fill_idx < 0 or fill_idx >= len(day0_bars):
        out.update(status="pending", reason="no_day0_minute_bars", pending_at=fill_day)
        return out

    remaining = 1.0
    partial_taken = False
    exits: list[dict] = []
    # The live ladder is the only harvest that raises the resting stop to entry after the
    # partial (breakeven). no_breakeven / t3 keep the hard stop; trail_only never partials.
    be_floor = harvest == "live_ladder" and breakeven_at_partial
    if breakeven_at_r is not None and harvest != "live_ladder":
        raise ValueError(f"breakeven_at_r set on harvest {harvest!r}, which has no "
                         "breakeven floor; the arm would silently do nothing")
    be_trigger = None
    if breakeven_at_r is not None:
        r_ps = r_frame_ps if r_frame_ps is not None else (entry - stop)
        be_trigger = entry + breakeven_at_r * r_ps

    def be_ambiguous(bar_low: float, bar_high: float, resting_level: float) -> bool:
        """Verbatim ep_replay._walk_leg.be_ambiguous: a bar reaching the trigger AND
        trading at/below entry, while not yet armed, cannot be ordered at this grain."""
        return (be_trigger is not None and resting_level < entry
                and bar_high >= be_trigger and bar_low <= entry)

    use_target = target is not None and harvest != "trail_only"

    def book(px: float, qty: float, reason: str, when: Any) -> None:
        exits.append({"time": str(when), "price": px, "reason": reason, "shares": qty,
                      "pnl": (px - entry) * qty})

    def pend(reason: str, at: date, left: float) -> dict:
        """The walk is blocked at `at` (a missing session, or a depth sale whose next open is not
        stored yet): pending, with the legs booked so far and `left` still open."""
        out.update(status="pending", reason=reason, pending_at=at)
        out["last_close"] = last_close  # HOOK
        out["exits"] = exits
        out["remaining"] = left
        return out

    def take_partial(px: float, when: Any) -> float:
        nonlocal remaining, partial_taken
        qty = remaining / 3
        if qty <= 0:
            return 0.0
        book(px, qty, "partial_profit", when)
        remaining -= qty
        partial_taken = True
        out["partial_fired"] = True
        return qty

    def stopped(px: float, when: Any) -> None:
        nonlocal remaining
        book(px, remaining, "stop_hit", when)
        remaining = 0.0
        out["final_reason"] = "stop_hit"

    # ── Day 0: the minute walk from the fill bar (stop-first; same-bar → abstain) ──
    cur_stop = float(stop)
    closed = False
    fb = day0_bars[fill_idx]
    if fb["l"] <= stop:
        if use_target and fb["h"] >= target:
            out.update(status="abstain", reason="day0_fill_bar_stop_and_target")
            return out
        # The fill is the first touch of the trigger; a close BELOW the stop proves the path
        # descended through it after that touch. A close at/above the stop leaves the order
        # unknowable at 1-min grain → abstain (never guess).
        if fb["c"] < stop:
            stopped(stop, fb["m"])
            closed = True
        else:
            out.update(status="abstain", reason="day0_fill_bar_straddles_stop")
            return out
    if not closed and use_target and fb["h"] >= target and fb["c"] >= stop:
        # target > entry ≥ the trigger, so a target touch inside the fill bar post-dates the
        # fill — orderable (the _walk_leg argument).
        if take_partial(target, fb["m"]) and be_floor:
            cur_stop = max(cur_stop, entry)
        if partial_taken:  # HOOK
            note_trigger("A", 0, cur_stop)  # HOOK
    if not closed and be_trigger is not None and fb["h"] >= be_trigger:
        # Same provable ordering the partial uses: the trigger is above entry, so a touch
        # >= trigger necessarily post-dates the fill; the fill bar's low is pre-fill and
        # cannot stop the newly-armed leg (its stop case already returned above).
        cur_stop = max(cur_stop, entry)
        note_trigger("B", 0, cur_stop)  # HOOK
    for b in day0_bars[fill_idx + 1:]:
        if closed:
            break
        hit_stop = b["l"] <= cur_stop
        hit_tgt = use_target and not partial_taken and b["h"] >= target
        if hit_stop and hit_tgt:
            out.update(status="abstain", reason="day0_stop_and_target_same_bar")
            return out
        if be_ambiguous(b["l"], b["h"], cur_stop):
            out.update(status="abstain", reason="day0_stop_and_breakeven_same_bar")
            return out
        if be_trigger is not None and b["h"] >= be_trigger:
            # past the ambiguity abstain above, this bar's low is > entry, so the raise
            # cannot stop the leg on this same bar.
            cur_stop = max(cur_stop, entry)
            note_trigger("B", 0, cur_stop)  # HOOK
        if hit_stop:
            px = b["o"] if (b["o"] is not None and b["o"] < cur_stop) else cur_stop
            if px != cur_stop:
                out["gap_through"] = True
            stopped(px, b["m"])
            closed = True
        elif hit_tgt:
            if take_partial(target, b["m"]) and be_floor:
                cur_stop = max(cur_stop, entry)
            if partial_taken:  # HOOK
                note_trigger("A", 0, cur_stop)  # HOOK
    if closed:
        out["exit_session"] = 0

    # ── Sessions after day 0: the live ladder + the broker's raise-only resting stop ──
    last_close = day0_bars[-1]["c"] if day0_bars else entry
    held_peak = _H.get("day0_close") or last_close  # HOOK: peak held close, for the chandelier / give-back rules
    horizon_reason = "open_at_horizon"
    if not closed:
        state = seed_exit_state(
            alert_date=fill_day, entry_price=entry, hard_stop=stop,
            remaining_shares=remaining, partial_taken=partial_taken,
            breakeven_active=partial_taken and be_floor, exits=list(exits))
        resting = cur_stop
        post_sessions = 0
        for idx, (d, b) in enumerate(sessions, start=1):
            if closed:
                break
            if b is None or b.get("c") is None or b.get("l") is None or b.get("h") is None:
                return pend(f"missing_session:{d.isoformat()}", d, state["remaining_shares"])
            out["sessions_walked"] = idx
            last_close = b["c"]
            held_peak = max(held_peak, b["c"])  # HOOK
            if be_ambiguous(b["l"], b["h"], resting):
                out.update(status="abstain", reason=f"fwd_stop_and_breakeven_same_day:{d.isoformat()}")
                return out
            if be_trigger is not None and b["h"] >= be_trigger:
                resting = max(resting, entry)
                note_trigger("B", idx, resting)  # HOOK
            hit_tgt = (use_target and not state["partial_taken"] and b["h"] >= target)
            if hit_tgt and b["l"] <= resting:
                out.update(status="abstain", reason=f"fwd_stop_and_target_same_day:{d.isoformat()}")
                return out
            if hit_tgt:
                remaining = state["remaining_shares"]
                partial_taken = state["partial_taken"]
                if take_partial(target, d) and be_floor:
                    resting = max(resting, entry)
                note_trigger("A", idx, resting)  # HOOK
                if _ref == "t20_entry_ref" and trig_rec["A"]["idx"] == idx:  # HOOK: #687's rule resets the stop to entry
                    resting = entry  # HOOK
                state["remaining_shares"] = remaining
                state["partial_taken"] = True
                state["breakeven_active"] = be_floor
                state["exits"] = list(exits)
                post_sessions = 0
            if harvest == "t3" and state["partial_taken"]:
                # ── the #2 lineage's post-partial walk (_walk_leg runner branch, mirrored):
                # hard stop stays, no breakeven, no trail; sell the runner at the 3rd close
                # after the partial session (the partial session itself is session 0).
                if hit_tgt:
                    continue
                post_sessions += 1
                remaining = state["remaining_shares"]
                if b["l"] <= stop:
                    px = b["o"] if (b["o"] is not None and b["o"] < stop) else stop
                    if px != stop:
                        out["gap_through"] = True
                    stopped(px, d)
                    closed = True
                    out["exit_session"] = idx
                    break
                if post_sessions >= 3:
                    book(b["c"], remaining, "time_close", d)
                    remaining = 0.0
                    out["final_reason"] = "time_close"
                    closed = True
                    out["exit_session"] = idx
                    break
                continue
            state["hard_stop"] = resting
            bar = {"l": b["l"], "c": b["c"]}
            ladder_kw: dict[str, Any] = {}
            if trail_mode == "pivot_swing":
                # the annotated stop for THIS session (idx is 1-based over `sessions`)
                bar["pivot_stop"] = pivot_stops[idx - 1] if idx - 1 < len(pivot_stops) else None
                ladder_kw["trail_mode"] = "pivot_swing"
            elif trail_mode == "character_ma":
                ladder_kw.update(trail_mode="character_ma",
                                 character_ma_window=int(character["home_window"]),
                                 character_ma_kind=str(character["home_kind"]),
                                 character_undercut=float(character["undercut_p80"]))
            # ── HOOK: candidate ownership (the default path below is the live call, unchanged) ──
            owned = _owned(idx)
            ratchet = "depth" if depth_exit else "plain"
            if owned and _rule in ("close_only", "sma10_depth", "sma20_depth"):
                step = apply_daily_exit_step(
                    state, bar, d,
                    integer_partial_shares=False,
                    skip_partial_decision=not ladder_partial,
                    prior_closes=(list(prior_closes) if trail_prior_closes else None),
                    trail_mode={"close_only": "sma", "sma10_depth": "sma10", "sma20_depth": "sma20"}[_rule])
                ratchet = "none" if _rule == "close_only" else "depth"
            elif owned:
                step = _synth_step(idx, d, b)
                ratchet = "plain"
            else:
                step = apply_daily_exit_step(
                    state, bar, d,
                    integer_partial_shares=False,
                    skip_partial_decision=not ladder_partial,
                    prior_closes=(list(prior_closes) if trail_prior_closes else None),
                    **ladder_kw)
            if _trace is not None:
                _trace.setdefault("sessions", []).append(dict(
                    idx=idx, d=str(d), o=b.get("o"), h=b["h"], l=b["l"], c=b["c"], owned=owned,
                    resting_in=resting, eff_stop=step.effective_stop, sma=getattr(step, "active_sma", None),
                    closed=step.closed, reason=step.close_reason))
            # ── END HOOK ──
            state.update(remaining_shares=step.new_remaining,
                         partial_taken=step.new_partial_taken,
                         breakeven_active=step.new_breakeven_active,
                         exits=step.new_exits,
                         running_closes=step.new_running_closes)
            if step.closed:
                px, reason, sale_session, sale_leg = step.close_price, step.close_reason, idx, {}
                if depth_exit and reason == "sma_trail_stop" and _ref != "control_at_close":  # HOOK: ref only
                    # #687: the depth rule decides on this TRUE close exactly as the ladder did, but
                    # the SALE is the next session's open (live: the 19:01 opening-auction order;
                    # paper: a DAY market order at the open) — `scripts/probes/_687/mechanics.py`
                    # `next_open`. Pending paths below book the legs and size BEFORE the close leg.
                    nxt = sessions[idx] if idx < len(sessions) else None
                    if nxt is None and idx >= horizon:
                        # decided on the last horizon session: the fill lies beyond the walk —
                        # written `horizon` with the mark, like any arm still open there, and
                        # the reason says the sale was decided (never settled at the close).
                        horizon_reason = f"depth_sale_decided_at_horizon:{d.isoformat()}"
                        break
                    if nxt is None:
                        # the next session is not settled yet: retried nightly, never leapt.
                        return pend("depth_next_open_not_yet_settled", d, remaining)
                    nd, nb = nxt
                    if nb is None or nb.get("o") is None:
                        return pend(f"missing_session:{nd.isoformat()}", nd, remaining)
                    px, sale_session, sale_leg = nb["o"], idx + 1, {"time": str(nd), "fill": "next_open"}
                    out["sessions_walked"] = idx + 1
                elif reason == "stop_hit" and b["o"] is not None and b["o"] < px:
                    px = b["o"]           # gap-through honesty: the resting stop fills at the open
                    out["gap_through"] = True
                exits = [dict(e) for e in step.new_exits]
                exits[-1] = {**exits[-1], "price": px,
                             "pnl": (px - entry) * exits[-1]["shares"], **sale_leg}
                out["final_reason"] = reason
                out["exit_session"] = sale_session
                remaining = 0.0
                closed = True
            else:
                exits = [dict(e) for e in step.new_exits]
                remaining = step.new_remaining
                if ratchet == "none":  # HOOK
                    pass  # HOOK
                elif ratchet == "depth":  # HOOK (was: if depth_exit:)
                    # #687: the resting stop is the live 16:45 job's own `depth_stop_price` on the
                    # same inputs it passes (today's effective stop = the line; this arm's hard
                    # stop; the row's breakeven flag; ADR20), ratcheted like the broker's
                    # raise-only `update_stop`. No ADR20 → the hard/breakeven floor, as live.
                    _dsp = depth_stop_price(  # HOOK: computed first so the trace can see it
                        line=step.effective_stop, hard_stop=stop, entry_price=entry,
                        breakeven_active=bool(state["breakeven_active"]),
                        adr20_pct=depth_adr20_pct)
                    _note_depth(idx, d, step, _dsp, resting)  # HOOK
                    resting = max(resting, _dsp)  # HOOK
                else:
                    resting = max(resting, step.effective_stop)
        out["partial_fired"] = any(e["reason"] == "partial_profit" for e in exits)

    out["exits"] = exits
    out["remaining"] = remaining
    out["last_close"] = last_close if not closed else None  # HOOK
    pnl = sum(e["pnl"] for e in exits)
    if closed:
        out.update(status="settled", pnl_per_share=pnl)
    elif out["sessions_walked"] >= horizon:
        out.update(status="horizon", reason=horizon_reason, final_reason="horizon",
                   mark_pnl_per_share=pnl + (last_close - entry) * remaining)
    else:
        out.update(status="pending", reason="open_walk_not_definitive")
    return out
